    "answer": "既无舍利，更取两尊烧。",
    "context": "丹霞天然禅师于慧林寺遇大寒，取木佛烧火取暖。院主呵曰：“何得烧我木佛？”师以杖拨灰曰：“吾烧取舍利。”院主曰：“木佛何有舍利？”师曰：“既无舍利，更取两尊烧。”院主随后眉须堕落。",
    "interpretation": "丹霞烧佛，非不敬佛，乃破学人执相之病——佛不在木雕泥塑中，佛在自心。木佛者，相也；佛者，性也。执相而迷性，何如破相而见性？“既无舍利，更取两尊烧”——此语如金刚剑，斩尽一切相执。院主眉须堕落，乃因执相之业火反烧自身——执佛相者，佛反成障。",
    "master": "丹霞天然",
    "source": "五灯会元 / 碧岩录",
