    "answer": "大好岭上云。",
    "context": "僧问天皇道悟禅师：“如何是西来意？”师曰：“大好岭上云。”僧曰：“意旨如何？”师曰：“可惜许，不知有祖师西来意。”",
    "interpretation": "天皇道悟以“岭上云”答“西来意”——云在岭上，自然自在，无心而住，无住而生。祖师西来意不在言语思量中，即此岭上白云，去来无心，即是西来意。僧人再问“意旨如何”，已落第二义——以意识分别解会，故道悟叹曰“可惜许”。",
