    "answer": "蹋着秤锤硬似铁。",
    "context": "此公案出自《五灯会元 / 传灯录》。学人就禅门关要参请石巩慧藏，问及“如何是佛？”。石巩慧藏直以“蹋着秤锤硬似铁。”答之，不涉浮言，直指心源。",
    "interpretation": "石巩以“蹋着秤锤硬似铁”答“如何是佛”——秤锤者，称量之具；蹋着者，亲身体验。佛不可以称量得——须亲践亲证。秤锤硬似铁，喻佛之实相——坚如金刚，不可破坏。学人以言语问佛，石巩以“蹋着”答之——佛不在言语中，须亲自蹋着、亲自证得。",
    "master": "石巩慧藏",
