    "interpretation": "赵州之“殿里底”——殿里者，泥塑木雕之佛像也。学人问佛，心中必有一清净庄严之佛相；赵州以“殿里底”（泥塑佛像）答之，令其佛相顿破。僧人追问“岂不是泥龛塑像”，赵州只答“是”——不辩解，不修正。赵州之意：佛不在泥塑木雕中，然亦不离泥塑木雕——即此泥塑佛像，当下一念不生时，即是真佛。不可执相求佛，亦不可离相求佛。",
