    "question": "如何是佛？",
    "answer": "去，莫向吾这里觅。",
    "context": "僧问黄檗希运禅师：“如何是佛？”师曰：“去，莫向吾这里觅。”",
    "interpretation": "黄檗之“去，莫向吾这里觅”——佛不在师处、不在别处，即在自己当下之心。学人向师求佛，已是向外求——黄檗以“去”喝退之，令其回光返照，向自心觅。如达摩答慧可：“将心来，与汝安。”——心不在别处，即此当下之心便是佛。",
