    "interpretation": "法眼以“山河大地”答“西来意”——祖师西来意不在别处，即此山河大地。山河大地非心外之境——乃唯心所现之相。法眼宗风以“一切现成”为旨——山河大地即是佛法，不须离山河大地别求佛法。悟得唯心时，则山河大地皆是自性之妙用。",
