    "question": "如何是祖师西来意？",
    "answer": "龟毛拂子，兔角杖子。",
    "context": "僧问洞山良价禅师：“如何是祖师西来意？”师曰：“龟毛拂子，兔角杖子。”",
    "interpretation": "洞山以“龟毛拂子，兔角杖子”答“西来意”——龟无毛，兔无角，此乃不存在之物。洞山以不存在之物答祖师西来意——意谓：祖师西来意如龟毛兔角，不可以有无说、不可以言语得。学人若以言语思量求祖师意，如求龟毛兔角——终不可得。唯超越有无、超越言语，方能亲见。",
