    "id": "koan-83",
    "question": "如何是祖师西来意？",
    "answer": "今日风起。",
    "context": "僧问鲁祖宝云禅师：“如何是祖师西来意？”师曰：“今日风起。”",
    "interpretation": "鲁祖以“今日风起”答“西来意”——风起者，自然之象。祖师西来意不在玄妙处，即此今日风起之自然。风起非造作——因缘时至，自然起风；道亦非造作——因缘时至，自然悟道。鲁祖以最自然之象示最玄妙之问——道法自然，不假功用。",
