    "answer": "且坐吃茶。",
    "context": "此公案出自《赵州语录 / 五灯会元》。学人就禅门关要参请赵州从谂，问及“如何是佛法大意？”。赵州从谂直以“且坐吃茶。”答之，不涉浮言，直指心源。",
    "interpretation": "赵州之“且坐吃茶”——与“吃茶去”异曲同工。佛法大意不在玄妙处，即此且坐吃茶之平常。学人问佛法大意，赵州以最平常之“且坐吃茶”答之——截断学人之玄妙期待。且坐者，安坐当下；吃茶者，平常心。即此安坐当下之平常心，便是佛法大意。",
