    "question": "如何是祖师西来意？",
    "answer": "神通并妙用，运水及搬柴。",
    "context": "庞蕴居士有偈曰：“日用事无别，唯吾自偶谐。神通并妙用，运水及搬柴。”",
    "interpretation": "庞蕴之“神通并妙用运水及搬柴”——神通妙用不在玄妙处，即此运水搬柴之平常。运水搬柴者，最平常之日常劳作——然悟自性者，于运水搬柴中显神通妙用。神通非飞天遁地——乃于平常中见不平常。如百丈“一日不作一日不食”——劳作即修行，平常即道。此为禅宗“平常心是道”之极致体现。",
    "master": "庞蕴",
