    "interpretation": "云门之“干屎橛”——干屎橛者，拭粪之木片——最不净之物。学人问佛，云门以最不净之物答之——此为禅宗破佛执之极致。学人执佛为崇高清净，云门以最卑下不净之物答之——破其高低净秽之分别。佛非崇高——佛在一切处，不择净秽。悟自性者，于干屎橛中见佛性——一切法皆是佛性之显现。",
