    "interpretation": "大珠之“本自悟”——悟者，本自悟。自性本具般若智——本自悟，不须更悟。然众生迷时，不见本自悟——故须修行以悟。既悟，即知本自悟——悟非得新物，乃知本自具足。如云开月现——月体本在（本自悟），云开（悟）后知月体本在。大珠以“本自悟”示学人：悟非从外得——乃知本自具足。",
