    "answer": "无不知。",
    "context": "僧问大珠慧海禅师：“如何是般若？”师曰：“无不知。”僧曰：“无不知，与知何异？”师曰：“知是分别，无不知是般若。”",
    "interpretation": "大珠之“无不知”——般若者，无不知。无不知非“无所不知”之知——乃超越分别之知。知者，分别心之知——以此知此，以彼知彼，有能有所；无不知者，般若智之知——无能无所，一时圆照。如镜照物——镜不分别好丑，物来即照——镜之“知”即“无不知”。般若亦如是——不分别而无所不知。",
