    "answer": "猛火燃眉毛。",
    "context": "此公案出自《赵州语录 / 五灯会元》。学人就禅门关要参请赵州从谂，问及“如何是禅？”。赵州从谂直以“猛火燃眉毛。”答之，不涉浮言，直指心源。",
    "interpretation": "赵州之“猛火燃眉毛”——猛火燃眉毛者，至急之事——不暇思量，须当下承担。禅亦如是——不暇思量，须当下承担。思量即落第二义——如猛火燃眉毛，不暇思量救不救，须当下扑灭。赵州以“猛火燃眉毛”示学人：禅在当下——不暇思量，须直下承担。",
    "master": "赵州从谂",
    "source": "赵州语录 / 五灯会元",
