    "question": "如何是道？",
    "answer": "白云覆青障，明月照澄江。",
    "context": "僧问法眼文益禅师：“如何是道？”师曰：“白云覆青障，明月照澄江。”",
    "interpretation": "法眼之“白云覆青障明月照澄江”——白云覆青障者，自然之景；明月照澄江者，自然之景。道不在别处，即此白云明月之自然。白云不须努力覆青障，明月不须努力照澄江——因缘和合，自然如此。道亦如是——不假造作，自然现前。法眼宗风以“一切现成”为旨——白云明月即一切现成之极致。",
