    "question": "如何是报身？",
    "answer": "光明。",
    "context": "此公案出自《五灯会元 / 传灯录》。学人就禅门关要参请大珠慧海，问及“如何是报身？”。大珠慧海直以“光明。”答之，不涉浮言，直指心源。",
    "interpretation": "大珠之“光明”——报身者，光明。报身者，修行所感之果报身——万德圆满，光明遍照。如日光明——不假造作，自然遍照。报身亦如是——修行圆满，自然光明遍照。然大珠非以光明为报身——乃以光明喻报身：报身如光明——圆满、遍照、无碍。",
