    "interpretation": "船子夹山——船子德诚传法于夹山善会后，翻船入水而逝——以生命印证法之传承。船子嘱夹山“藏身处没踪迹没踪迹处莫藏身”——藏身于无踪迹处（不住有为），然无踪迹处亦莫藏身（不住无为）——超越有无二边。竿头丝线从君弄——如钓鱼者竿头丝线，任君摆弄——不执着于法；不犯清波意自殊——虽垂丝于水，然不染着于水——虽在世间，然不染世间。船子以渔父之喻示禅之自在——在世而不染世。",
