    "interpretation": "赵州之“落汤鸡”——落汤鸡者，鸡落水中——浑身湿透，狼狈不堪。赵州以“落汤鸡”答西来意——意谓：祖师西来意如落汤鸡——浑身湿透，一切庄严相尽失。学人问西来意，心中必有庄严之概念——赵州以最不庄严之“落汤鸡”答之——破其庄严执。道不在庄严处——即此最不庄严之落汤鸡，便是西来意。",
    "master": "赵州从谂",
    "source": "赵州语录 / 五灯会元",
