    "question": "鸟窠吹毛",
    "answer": "吹毛。",
    "context": "白居易问鸟窠道林禅师：“如何是佛法大意？”师吹布毛，曰：“如是。”白居易不悟。",
    "interpretation": "鸟窠吹毛——白居易问佛法大意，鸟窠吹布毛曰“如是”——吹毛者，最平常之动作。佛法大意不在玄妙处，即此吹毛之当下。然白居易不悟——以思量分别求佛法大意，不能于吹毛之当下见自性。鸟窠以最平常之吹毛示佛法大意——道在日用中，不在玄妙处。然悟与不悟，唯在学人——师家可以直指，不可以代悟。",
