    "interpretation": "无门慧开以赵州“狗子无佛性”为《无门关》开篇第一则。佛经明言丗生皆有佛性，赵州却答“无”，不是拨无佛性，而是以一字斩断学人“有”“无”的思量分别。无门令学人参这个“无”字——不作虚无会，不作有无会，只管提撕，通身起疑团，如吞热铁丸，吐又吐不出，久久纯熟，蓦然打发，惊天动地。",
