    "question": "百予野狐",
    "answer": "不如一吐。",
    "context": "百丈怀海禅师每升堂常说：“文殊、普贤、远公、水海不可不是大善知识。有一般寺院却不许他知。”无门慧开评日：“他既是大善知识，为什么不许他知？”——《无门关》第二则。",
    "interpretation": "百丈之“不许知”，意在斜断学人以知见卜度为悟。知见即是污染，“不知”方是净土。无门评日：“要是他知，便是陆羽公、水海；他若不知，便是饱食醒眠的污泥。”——知与不知，两边不立，方是无门意。",
