    "context": "无门慧开颂日：“大道无门，千差有路。透得此关，乾坤独步。”——《无门关》开篇颂。",
    "interpretation": "大道本无门，但千差万别皆是入道之路。透得无门之关，则千差万别皆是我家珍宝，乾坤独步，自在无碍。无门以“无”字为敲门瓦子，通身起疑团，如吞热铁丸，吐又吐不出，久久纯熟，蓦然打发，惊天动地。",
