    "id": "koan-243",
    "question": "一茎草上现琼楼玉殿",
    "answer": "若端的得一回汗出，便向一茎草上现琼楼玉殿。若未端的得一回汗出，纵有琼楼玉殿，却被一茎草盖却。",
    "context": "大慧宗杲举白云端师翁语：若端的得一回汗出也，便向一茎草上现琼楼玉殿。若未端的得一回汗出，纵有琼楼玉殿，却被一茎草盖却。大慧云：一茎草上现琼楼玉殿，决定可信。琼楼玉殿被一茎草盖却，莫被他热谩。",
    "interpretation": "一茎草现琼楼玉殿——悟则一茎草即是琼楼玉殿，一物全彰。琼楼玉殿被一茎草盖却——未悟则琼楼玉殿亦被一茎草遮蔽，不见全体。大慧补一句“莫被他热谩”——莫被言语瞒过，须实参实悟。此则体现大慧宗风：不废言句而不死于言句。",
    "master": "大慧宗杲",
    "source": "大慧语录卷第二",
