    "question": "径山无寸土庄田",
    "answer": "径山无寸土庄田，今夏随宜结众缘。慵论道懒谈禅。拄杖挑来个个圆。不用息心除妄想，大家吃饭了噇眠。",
    "context": "大慧宗杲上堂云：径山无寸土庄田，今夏随宜结众缘。慵论道懒谈禅。拄杖挑来个个圆。不用息心除妄想，大家吃饭了噇眠。噇眠则不无，或若梦中有人索饭钱又作么生。",
    "interpretation": "不用息心除妄想——妄想本空，何须更息？吃饭噇眠——日用即是修行，何须别求？然大慧又追问“梦中有人索饭钱又作么生”——日用虽是修行，若在梦中（无明中）仍被业力牵引，则吃饭噇眠又成业障。此则看似轻松，实则深峻：即俗即真，而又不可安于俗。",
    "master": "大慧宗杲",
    "source": "大慧语录卷第一",
