    "question": "博山看“三千里外”语，为何打失布袋？",
    "answer": "如放下千斤担子，自谓大悟——逮见宝方，方知未了。",
    "context": "博山自述：当时看船子和尚“没踪迹”句，一日因阅《传灯录》，见赵州嘱僧云“三千里外逢人始得”，不觉打失布袋，如放下千斤担子，自谓大悟。逮见宝方和尚，如方木逗圆孔，始具惭愧。乃叹云：若悟后不见大善知识，纵得安逸，终是未了。",
    "interpretation": "此段自叙悟缘，正是《警语》全书之骨血。博山悟后不以此自足，反去见宝方和尚勘验，一勘便知往日“大悟”只是解路——如方木逗圆孔，方圆不合。由此乃有“我得宝方不肯两个字，受用不尽”之叹。禅师尚且如此，后人稍有心境相应、光影门头便自称彻悟，可不惧哉？博山一生痛陈禅病、教人悟后须见人，皆从这段亲历中来。",
