    "id": "koan-292",
    "question": "前面万丈深坑，背后野火来逼，两畔荆棘林，作么生免得？",
    "answer": "直须不顾危亡，始得个彻头——稍生疑议，则丧身失命。",
    "context": "芭蕉示众：如人行次，忽遇前面万丈深坑，背后野火来逼，两畔是荆棘林。若也向前，则堕在坑堑；若也退后，则野火烧身；转侧则被荆棘林碍。当与恁么时，作么生免得？若也免得，有出身之路；若免不得，堕身死汉。博山评：此语最为工夫紧要。学者多求知解，堕在玄奥窠臼里，不向这里留意，是谓空过一生。",
    "interpretation": "芭蕉以绝境喻参禅：进不得、退不得、躲不得——正是不许你左思右卜、稍生疑议之处。博山谓做工夫做到无可用心处、万仞悬崖处、水穷山尽处、罗纹结角处，如老鼠入牛角，自有倒断。绝处正是出身之路：疑情逼到无路可走，一时桶底脱落。今人参禅稍有难处便求解会、问人讨说法，正是“免不得”的堕身死汉——不肯死于疑团，便不得活于悟门。",
