    "question": "师唱谁家曲，宗风嗣阿谁？",
    "answer": "隔江打鼓不闻声。",
    "context": "此公案记于《杨岐方会和尚后录》。学人参谒杨岐方会，问“师唱谁家曲，宗风嗣阿谁？”，杨岐方会遂应机答曰“隔江打鼓不闻声。”。机锋电掣，当下截断学人意根思量。",
    "interpretation": "僧问杨岐宗风嗣承谁家，杨岐答“隔江打鼓不闻声”——暗示宗风传承不在言语声相中，超越音声形相，直指心印。",
