    "context": "此公案记于《《杨岐方会和尚语录》》。学人参谒daowu-zhen，问“道吾真明暗截断众流”，daowu-zhen遂应机答曰“僧问：“承师有言，明暗两字截断众流，请师便道。”师云：“作么生道。”僧云“作家”，师便喝，僧抚掌，师云“恰是”。”。机锋电掣，当下截断学人意根思量。",
    "interpretation": "以明暗截断一切分别之流。僧以“作家”回应，师以喝截之，僧抚掌——默契。师云“恰是”——正是如此，不在言语中。",
