    "answer": "向汝道，汝不信。合取狗口。",
    "context": "黄龙慧南禅师续补中，僧问“如何是佛”，师云“向汝道汝不信”。僧云“请师指示”，师云“合取狗口”。禅师以凌厉之语截断学人知解——佛不可说，说了你也不信，不如合嘴。",
