    "answer": "空谷景隆论晦庵墙壍之害。皮肤之学者偏要排佛，才读数十卷书心忿忿然遽以排佛为急务。学至宏博自然通泰排佛之心稍觉轻矣。学而至化出彼墙壍之外自知排佛之非追悔不及矣——须学到变化之地步方能跳出晦庵所设的障蔽。",
