    "question": "忽遇明镜来时如何？",
    "answer": "百杂碎。",
    "context": "雪峰示众：我这里如一面古镜相似，胡来胡现，汉来汉现。时有僧问：忽遇明镜来时如何？峰云：胡汉俱隐。僧举似玄沙，师云：我不与么道。僧问：忽遇明镜来时如何？师云：百杂碎。",
    "interpretation": "雪峰以古镜喻心：物来则现，物去不留，胡汉俱隐处犹有镜在。玄沙“百杂碎”更进一步——能照之镜亦打成一片，能所俱泯，纤尘不立。镜未碎时，尚有照与不照之功夫；百杂碎后，方是玄沙绵密宗风之彻底处。",
