    "context": "僧问赵州：万法归一，一归何处？州云：我在青州作一领布衫，重七斤。高峰拈云：赵州一段绵密工夫，风吹不入雨打不湿，惜乎不解相体裁衣，翻成钝置。高峰则不然，忽有人问：万法归一，一归何处？只向他道：我二十年前曾向遮里打失一只眼睛，至今指鹿为马。",
