    "context": "陆亘大夫问南泉：弟子家中于一瓶内养得一鹅儿，今来长大，欲出此鹅，且不得打破瓶，亦不得损却鹅。泉召云：大夫！大夫应诺。泉云：出也。高峰拈云：南泉潦倒，手眼不亲，纵饶出得，也是死货。高峰只向他道：大夫还曾示人么？才拟祗对，便与乱棒打出。",
