    "interpretation": "高峰悟道因缘——参'无'字三年不成片，改参'万法归一'六日即悟。悟后答雪岩'狗舔热油铛'——热油铛舔不得放不下，正是疑情成片之喻。'正要和尚疑着'示悟后机锋不让。",
