    "context": "雪峰与岩头、钦山同行参方，至鳌山阻雪。雪峰终日危坐，岩头鼾睡如雷。雪峰诉参德山之疑，岩头一语点破，雪峰忽悟德山所示之旨，叹曰：鳌山成道，何处不通。",
    "interpretation": "雪峰行脚多年未悟，在鳌山阻雪时被岩头一语点破——悟道不在行脚遍参，在于一言之下桶底脱落。'鳌山成道何处不通'示悟后一切处皆是道场，不必更向外求。",
