    "id": "koan-441",
    "question": "雪峰洞山淘米",
    "answer": "沙米一时去。",
    "context": "雪峰在洞山作饭头，淘米次，山问：淘沙去米？淘米去沙？师曰：沙米一时去。山曰：大众吃个什么？师遂覆却米盆。山曰：据于因缘，合在德山。",
    "interpretation": "洞山问淘沙去米还是淘米去沙——雪峰答沙米一时去，示不落二边。洞山追问大众吃什么，雪峰覆却米盆——全体放下，更无一粒米可得。洞山印之曰合在德山，预示雪峰当于德山座下开悟。",
    "master": "雪峰义存",
