    "id": "koan-443",
    "question": "雪峰寸丝不挂",
    "answer": "大好寸丝不挂。",
    "context": "师问僧：名什么？僧云：玄机。师云：日织多少？僧云：寸丝不挂。师云：参堂去。僧行三五步，师云：袈裟落地也。僧回首，师便打，云：大好寸丝不挂。",
    "interpretation": "僧自称寸丝不挂，雪峰以袈裟落地验之——僧回首即落第二念。雪峰打云大好寸丝不挂——寸丝不挂不是口头禅，回首即是挂。此是雪峰勘验学人是否真到寸丝不挂之境。",
    "master": "雪峰义存",
    "source": "雪峰义存禅师语录",
