    "question": "雪峰透网金鳞",
    "answer": "待汝透出网来，即向汝道。",
    "context": "三圣问师：透网金鳞，以何为食？师云：待汝透出网来，即向汝道。圣云：一千五百人善知识，话头也不识。师云：老僧住持事烦。",
    "interpretation": "三圣问透网金鳞以何为食——喻悟后之人如何保任。雪峰答待汝透出网来即向汝道——反问三圣是否真透网。三圣云一千五百人善知识话头也不识——评雪峰不答。雪峰云老僧住持事烦——不辩不争，亦是作家本色。",
