    "question": "密庵无心无法",
    "answer": "佛说一切法，为度一切心。我无一切心，何用一切法。",
    "context": "密庵上堂：佛说一切法，为度一切心。我无一切心，何用一切法。既无心，又无法，山河大地甚处得来。见闻觉知复是何物。乃喝一喝云：临崖看浒眼，特地一场愁。",
    "interpretation": "密庵上堂直示心法双遣——佛说一切法为度一切心，我无一切心何用一切法。既无心又无法，山河大地从何而来，见闻觉知复是何物。喝一喝云临崖看浒眼特地一场愁——心法双遣之后，山河大地见闻觉知皆不可得，惟有临崖看浒之愁。",
    "master": "密庵咸杰",
