    "question": "密庵评三圣兴化",
    "answer": "二尊宿美则美矣，若要扶临济正宗，每人各欠一顿棒在。",
    "context": "密庵举三圣道我逢人则出出则不为人，兴化道我逢人则不出出则便为人。白云端和尚拈云二尊宿各有一处打得着。密庵召大众云：白云端和尚也好与三十棒。复举保寿开堂三圣推出一僧保寿便打，三圣云与么为人瞎却镇州一城人眼去在，保寿掷下拄杖归方丈。师云：二尊宿美则美矣，若要扶临济正宗，每人各欠一顿棒在。",
    "interpretation": "密庵评三圣兴化二尊宿——美则美矣若要扶临济正宗每人各欠一顿棒在。此是密庵力扶临济正宗之语：二尊宿虽各有一处打得着，然犹欠一顿棒——未到彻底处。密庵以棒喝为临济正宗之标识，力扶宗风。",
    "master": "密庵咸杰",
    "source": "密庵咸杰禅师语录",
