    "answer": "知幻即离，不作方便。离幻即觉，亦无渐次。",
    "context": "密庵上堂：知幻即离，不作方便。以拂子左边击一下云：向这里荐取。离幻即觉，亦无渐次。以拂子右边击一下云：向这里荐取。一人发真归元，十方虚空悉皆消殒。以拂子中间划一划。",
    "interpretation": "密庵上堂引圆觉经——知幻即离不作方便，离幻即觉亦无渐次。以拂子左边击一下云向这里荐取，右边击一下云向这里荐取，中间划一划——三处示众，直指当下。一人发真归元十方虚空悉皆消殞——直示悟后之境。",
