    "context": "密庵上堂举婆子供养庵主公案：婆子令女子抱定云正与么时如何，主云枯木倚寒巖三冬无暖气。女子归举似婆，婆云我二十年只供养个俗汉。遂遣去。密庵举此公案勘验学人——枯木倚寒巖是落空还是真到？",
    "interpretation": "密庵举婆子供养庵主公案——庵主答枯木倚寒巖三冬无暖气，婆子云我二十年只供养个俗汉。枯木倚寒巖看似有境，实则落空——婆子识得落空，遂遣去。密庵举此直示学人不可落于枯木寒巖之空境。",
