    "question": "密庵有物先天地",
    "answer": "有物先天地，无形本寂寥。能为万象主，不逐四时凋。",
    "context": "密庵上堂：有物先天地，无形本寂寥。能为万象主，不逐四时凋。且道是什么物。有般无鼻孔汉便道描也描不成画也画不就，佛眼觑不见，不识不知。如斯理论，正所谓一句合头语，万劫系驴橛。",
    "interpretation": "密庵上堂引傅大士诗——有物先天地无形本寂寥，能为万象主不逐四时凋。且道是什么物——直示学人参究。有般无鼻孔汉便道描也描不成——落于玄妙。密庵力斥一句合头语万劫系驴橛——不可落于合头语。",
