    "answer": "祖师门下，直截省要，不历阶梯，立地成佛。",
    "context": "密庵法语示昺禅人：祖师门下，直截省要，不历阶梯，立地成佛。学道人多不明此，病在于何。只为太杀现成，不肯承当。一味钻头入知见网中，觅佛觅法，觅玄觅妙，向上向下，如何若彼。恰如苍蝇堕在漆盘中，粘手缀脚。",
    "interpretation": "密庵法语直示祖师门下直截省要不历阶梯立地成佛——学道人多不明此，病在太杀现成不肯承当。一味钻头入知见网中觅佛觅法觅玄觅妙——恰如苍蝇堕在漆盘中粘手缀脚。密庵力斥知见网中之口头禅。",
