    "context": "密庵法语示应禅人：昔世尊在灵山会上百万众前拈起一枝花，独迦叶尊者一人破颜微笑。世尊便云吾有正法眼藏涅槃妙心分付摩诃迦叶。劈头一错，直至如今，代代相传，分宗列派，承虚接响。",
    "interpretation": "密庵法语示应禅人——世尊拈花迦叶微笑，劈头一错直至如今代代相传分宗列派承虚接响。密庵以劈头一错直指拈花微笑之旨——不可落于代代相传之虚响，须识得拈花之落处。",
