    "answer": "曹溪一滴，源深流长，至于临济，其道益张。",
    "context": "密庵塔铭由正议大夫刑部尚书葛邲撰：释迦如来灭度之后，其徒未免囿于名相。至达磨西来不立文字直指人心见性成佛。六传而至大鉴，五宗而得临济。曹溪一滴源深流长，至于临济其道益张。如击石火如闪电光，不离当处觌面承当。猗欤杰公直造其堂，行解相应非断非常，一音演畅七坐道场。",
    "interpretation": "密庵塔铭记其一生——曹溪一滴源深流长至于临济其道益张。如击石火如闪电光不离当处觌面承当。猗欤杰公直造其堂行解相应非断非常一音演畅七坐道场——密庵承临济正宗，七镇名山，行解相应，为南宋临济宗中坚。",
