    "question": "紫柏煆昏散",
    "answer": "消昏散于刹那，扶止观于大寂。",
    "context": "紫柏著天池山煆昏散道场说：原未煆昏散之椎轮，三世诸佛迭相授受者也。第在用之何如耳。用之果善，消昏散于刹那、扶止观于大寂，陨山河于未始有地、荡身心于无得之乡，断欲结之利刀、资灵躯之正命。",
    "interpretation": "紫柏以煆炼昏沉散乱为做工夫之要——昏沉散乱是参禅两大病，须以决志逼拶煆炼如以火煆金。消昏散于刹那扶止观于大寂——煆昏散非止非观，须以决志逼拶，令昏散消落心体光洁方有悟分。",
