    "interpretation": "紫柏解毗舍浮佛颂——一切自在觉，既自在觉矣有何物而为障碍。然未觉者不免触途成滞——见色被色障碍见空被空障碍有身被身障碍有心被心障碍。悟得自在觉则一切处无碍，未悟则触途成滞。",
