    "context": "紫柏尊者别集附录由陆符撰：师讳真可达观其字也晚自号紫柏。万历中慈圣皇太后钦师道风上亦雅知师谓若此真可名一僧。师遂取以更其名云。世家吴江之摊缺沈姓父连字季子。师相好魁奇雄硕威掩万众童真绝染肤体如铁石。日饭数升过中不食。自出家即胁不到席四十余年如一日。",
    "interpretation": "陆符撰紫柏附录——师讳真可达观其字也晚自号紫柏。万历中慈圣皇太后钦师道风上亦雅知师谓若此真可名一僧。师相好魁奇雄硕威掩万众童真绝染肤体如铁石，自出家即胁不到席四十余年如一日——此为研究紫柏生平之重要史料。",
