    "id": "koan-512",
    "question": "临济四料拣夺人不夺境",
    "answer": "煦日发生铺地锦，婴儿垂发白如丝。",
    "context": "临济初至河北住院，见普化克符二上座，乃谓曰：我欲于此建立黄檗宗旨，汝可成褫我。二人珍重下去。三日后普化却上问云：和尚三日前说什么。师便打。三日后克符上来问：和尚昨日打普化作什么。师亦打。至晚小参云：我有时夺人不夺境，有时夺境不夺人，有时人境俱夺，有时人境俱不夺。僧问：如何是夺人不夺境。师云：煦日发生铺地锦，婴儿垂发白如丝。大慧云：此二句，一句存境，一句夺人。",
    "interpretation": "临济四料拣之一——夺人不夺境。煦日发生铺地锦（存境），婴儿垂发白如丝（夺人）。大慧评此二句一句存境一句夺人——破除对自我的执着而保留外境。临济以诗偈示四料拣之旨，以不同方式接引不同根器的学人。",
    "master": "临济义玄",
    "source": "人天眼目",
    "relatedConcepts": ["siliao-jian"],
    "relatedPersons": ["linji"],
    "relatedBooks": ["renyantianmu"]
