    "interpretation": "临济四喝——金刚王宝剑/踞地师子/探竿影草/不作一喝用。临济以四喝接引学人，僧拟议师便喝——一喝之下截断情识。寂音尊者颂四喝之旨：金刚王剑觌露堂堂才涉唇吻即犯锋铓，踞地师子本无窠臼顾伫未拟即俱丧偶。",
