    "question": "临济三玄三要",
    "answer": "一句中须具三玄，一玄中须具三要。",
    "context": "师上堂云：大凡举唱宗乘，须辨宾主。一句中须具三玄，一玄中须具三要。汾阳颂总：三玄三要事难分，得意忘言道易亲。一句明明该万象，重阳九日菊花新。慈明颂：三玄三要，佛祖要妙。体中玄兮，句里玄兮，玄中玄兮。三要者，一言中具三要也。",
    "interpretation": "临济三玄三要——一句中须具三玄，一玄中须具三要。汾阳颂三玄三要事难分得意忘言道易亲——三玄三要之旨在于得意忘言。慈明颂三玄三要佛祖要妙——体中玄句里玄玄中玄，一言中具三要。",
    "master": "临济义玄",
    "source": "人天眼目",
