    "question": "临济四照用",
    "answer": "先照后用、先用后照、照用同时、照用不同时。",
    "context": "师上堂云：我有时先照后用，有时先用后照，有时照用同时，有时照用不同时。慈明颂：先照后用，月在云中。先用后照，箭离弓弦。照用同时，如镜照像。照用不同时，或先或后。",
    "interpretation": "临济四照用——先照后用/先用后照/照用同时/照用不同时。照则照破学人执着令见本来面目，用则棒喝交驰截断学人情识。慈明颂四照用之旨——先照后用月在云中，先用后照箭离弓弦，照用同时如镜照像。",
