    "context": "巴陵颢鉴禅师，云门侍者。师问：教意有几种。陵曰：祖祢不了，殃及儿孙。师曰：教意有几种。陵曰：我有三句，示诸学人。一曰：鸡寒上树，鸡寒入瓮。二曰：金将火试。三曰：透网金鳞。大慧云：巴陵三句，即云门三句之别名也。",
    "interpretation": "巴陵三句——鸡寒上树/金将火试/透网金鳞。巴陵颢鉴为云门侍者，其三句即云门三句之别名。大慧评巴陵三句即云门三句之别名——鸡寒上树即函盖乾坤，金将火试即截断众流，透网金鳞即随波逐浪。",
