    "id": "koan-522",
    "question": "曹洞五位君臣",
    "answer": "正中偏、偏中正、正中来、兼中至、兼中到。",
    "context": "僧问曹山五位君臣旨诀。山云：正位即属空界，本来无物。偏位即色界，有万形象。偏中正者，舍事入理。正中来者，背理就事。兼带者，冥应众缘，不随诸有，非染非净，非正非偏。故曰虚玄大道无著真宗。从上先德，推此一位，最妙最玄，当审详辨。大阳颂：不立功勋坐庙堂，群臣何敢望清光。潭潭禁殿尊严甚，寂寞无人夜未央（君）。",
    "interpretation": "曹洞五位君臣——正中偏/偏中正/正中来/兼中至/兼中到。曹山云正位即属空界本来无物，偏位即色界有万形象。偏中正者舍事入理，正中来者背理就事，兼带者冥应众缘不随诸有。大阳颂不立功勋坐庙堂群臣何敢望清光——以君臣关系比喻理事关系。",
