    "id": "koan-525",
    "question": "沩仰三种生",
    "answer": "想生、相生、流注生。",
    "context": "沩山谓仰山曰：吾以镜智为宗要，出三种生。所谓想生相生流注生。楞严经云：想相为尘，识情为垢，二俱远离，则汝法眼应时清明，云何不成无上知觉。想生即能思之心杂乱，相生即所思之境历然，微细流注，俱为尘垢。若能净除此三生，则法眼清明。后有僧问石佛忠禅师：如何是想生。忠云：兔子望月。如何是相生。忠云：山河大地。如何是流注生。忠云：无间断。",
    "interpretation": "沩仰三种生——想生/相生/流注生。沩山以镜智为宗要出三种生——想生即能思之心杂乱，相生即所思之境历然，微细流注俱为尘垢。楞严经云想相为尘识情为垢二俱远离则法眼清明。石佛忠解想生为兔子望月相生为山河大地流注生为无间断。",
    "master": "沩山灵祐",
    "source": "人天眼目",
    "relatedConcepts": ["siliao-jian"],
    "relatedPersons": ["weishan-lingyou"],
    "relatedBooks": ["renyantianmu"]
