    "answer": "生缘、佛手、驴脚。",
    "context": "黄龙慧南禅师，室中常问僧：人人尽有生缘，上座生缘在甚处。又问：我手何似佛手。又问：我脚何似驴脚。凡三十年，莫有契其机者。丛林目为黄龙三关。南公自颂：生缘有语人皆识，水母何曾吃得虾。我手佛手兼举，禅人直下荐取。我脚驴脚并行，步步踏著无生。",
    "interpretation": "黄龙三关——生缘/佛手/驴脚。黄龙慧南室中常问三关——人人尽有生缘上座生缘在甚处，我手何似佛手，我脚何似驴脚。凡三十年莫有契其机者。三关之旨在截断学人情识令于言语路绝处荐得。南公自颂生缘有语人皆识水母何曾吃得虾。",
