    "context": "汾阳善昭禅师示众云：我有十智同真，与诸人商量。一者同一质，二者同一事，三者同一照，四者同一体，五者同一用，六者同一性，七者同一机，八者同一境，九者同一声，十者同一力。汾阳颂总：十智同真事本圆，于一真界任方圆。纵横自在无拘系，万象森罗一镜悬。",
