    "question": "拈花公案",
    "answer": "世尊拈花，迦叶微笑。",
    "context": "王荆公问佛慧泉禅师云：禅家所谓世尊拈花，出在何典。泉云：藏经亦不载。公曰：余顷在翰苑，偶见大梵天王问佛决疑经三卷，因阅之。经文所载甚详。梵王至灵山，以金色波罗花献佛，舍身为床座，请佛为众生说法。世尊登座，拈花示众。众皆默然。唯迦叶破颜微笑。世尊云：吾有正法眼藏，涅槃妙心，实相无相，微妙法门，不立文字，教外别传，付嘱摩诃迦叶。",
    "interpretation": "拈花公案——世尊拈花迦叶微笑。王荆公问佛慧泉禅师世尊拈花出在何典，泉云藏经亦不载。公于翰苑偶见大梵天王问佛决疑经三卷，经文所载甚详——梵王以金色波罗花献佛，世尊拈花示众众皆默然唯迦叶破颜微笑，世尊云吾有正法眼藏涅槃妙心付嘱摩诃迦叶。",
