    "question": "五家要括",
    "answer": "临济/沩仰/曹洞/云门/法眼五家法脉。",
    "context": "人天眼目卷之六末载五家要括：临济——南岳马祖百丈运，临兴南穴首山汾慈明南会开二续，心出新清端演勤。沩仰——百丈派出大沩祐，香严仰山亲得绍，南塔芭蕉清续传，儿孙未见继其后。曹洞——青石药山云洞祖，云膺同安丕志附，梁山亲得大阳玄，投子芙蓉淳独步。云门——青石天龙接德山，雪峰云门香林远，北塔雪窦付天衣，二本从兹门大显。法眼——雪峰傍出玄沙备，地藏法眼益尊贵，韶国师传寿与津，佛法新罗而已耳。",
    "interpretation": "五家要括——临济/沩仰/曹洞/云门/法眼五家法脉。临济自南岳马祖百丈传下，沩仰自百丈派出大沩祐，曹洞自青石药山云洞祖传下，云门自青石天龙接德山雪峰云门传下，法眼自雪峰傍出玄沙备传下。五家要括以诗偈概括五家法脉传承。",
    "master": "晦岩智昭",
    "source": "人天眼目",
