    "interpretation": "唐僧元晓独行荒陂夜宿冢间，渴甚掬水于穴中得泉甘凉，黎明视之髑髅也。大恶之尽欲呕去，忽猛省叹曰心生则种种法生心灭则髑髅不二——此是元晓以掬水髑髅之因缘悟唯心之旨。同一水也，夜以为是甘泉，晨以为是从髑髅出——心生则种种法生心灭则髑髅不二。",
