    "answer": "见衲子必探其道学，尤通首楞严，尝自疏其义。",
    "context": "王文公罢相归老钟山，见衲子必探其道学，尤通首楞严，尝自疏其义。其文简而肆，略诸师之详；而详诸师之略，非识妙者莫能窥也。每曰：今凡看此经者，见其所示本觉妙明、性觉明妙，知根身器界生起不出我心，窃自疑今钟山老僧之心，岂亦能造万法乎？",
    "interpretation": "王荆公（王安石）罢相归老钟山，见衲子必探其道学尤通首楞严尝自疏其义——此是王安石归老后对佛法之深入。其文简而肆略诸师之详而详诸师之略非识妙者莫能窥也——惠洪评王安石之楞严疏。每曰今凡看此经者见其所示本觉妙明性觉明妙知根身器界生起不出我心——此是王安石对楞严经之理解。",
