    "question": "南禅师光属屋庐",
    "answer": "光属屋庐，诫侍者勿言于外。",
    "context": "南禅师居积翠时，一夕燕坐，光属屋庐，诫侍者勿言于外。嵩明教既化，火浴之，顶骨、眼睛、齿舌、耳毫、男根、数珠皆不坏。如世尊言：比丘生身不坏，发无垢智光者，善根功德之力，如来知见之力。故行住坐卧，须内外清净，不可使一物有碍也。",
    "interpretation": "南禅师居积翠时一夕燕坐光属屋庐诫侍者勿言于外——此是黄龙慧南之禅定光相。嵩明教既化火浴之顶骨眼睛齿舌耳毫男根数珠皆不坏——此是嵩明教之生身不坏。惠洪引世尊言比丘生身不坏发无垢智光者善根功德之力如来知见之力——此是惠洪对生身不坏之解释。",
