    "question": "大慧赞佛离生灭",
    "answer": "世间离生灭，犹如虚空华，智不得有无，而兴大悲心。",
    "context": "尔时大慧菩萨与摩帝菩萨，俱游一切诸佛刹土，承佛神力，从坐而起偏袒右肩，右膝著地，合掌恭敬，以偈赞曰：世间离生灭，犹如虚空华，智不得有无，而兴大悲心。一切法如幻，远离於心识，智不得有无，而兴大悲心。",
    "interpretation": "大慧菩萨赞佛偈——世间离生灭犹如虚空华智不得有无而兴大悲心。此偈赞佛离生灭见不住有无而兴大悲——世间本离生灭犹如虚空华，智者不得有无而兴大悲心度众生。一切法如幻远离於心识——离心识则一切法如幻，智不得有无而兴大悲。此是楞伽经之宗要——离生灭离心识不住有无而兴大悲。",
