    "id": "koan-554",
    "question": "自心现境界",
    "answer": "自心现境界，善解其义。种种众生、种种心色，无量度门，随类普现。",
    "context": "与大比丘僧及大菩萨众俱，从彼种种异佛刹来。是诸菩萨摩诃萨，无量三昧自在之力，神通游戏，大慧菩萨摩诃萨而为上首。一切诸佛手灌其顶，自心现境界，善解其义。种种众生、种种心色，无量度门，随类普现。於五法自性、识、二无我究竟通达。",
    "interpretation": "楞伽经开篇即明自心现境界善解其义——一切境界皆自心现，善解其义者知自心现量离心无别法。种种众生种种心色无量度门随类普现——此是自心现量之妙用。於五法自性识二无我究竟通达——此是楞伽经之教理纲宗。",
    "master": "释迦牟尼",
