    "question": "百八问",
    "answer": "大慧菩萨百八问，问佛一切法。",
    "context": "尔时大慧菩萨摩诃萨，承佛威神，白佛言：世尊！我今应於世尊所，咨问所疑。我及一切诸菩萨众，设欲请问，如来应供等正觉，为我说法。佛告大慧：恣所欲问，我当为汝解释所疑。大慧菩萨摩诃萨，即问佛言：世尊！云何净其一切自心现？云何生起有与无？云何见痴与惑？云何起作？",
    "interpretation": "大慧菩萨承佛威神白佛言——我今应於世尊所咨问所疑。佛告大慧恣所欲问我当为汝解释所疑——大慧菩萨即问佛言云何净其一切自心现云何生起有与无云何见痴与惑云何起作。此是楞伽经百八问之开端——大慧菩萨以百八问问佛一切法，佛一一答之。",
