    "id": "koan-556",
    "question": "藏识海常住",
    "answer": "譬如巨海浪，斯由猛风起，洪波鼓冥壑，无有断绝时。藏识海常住，境界风所动，种种诸识浪，腾跃而转生。",
    "context": "佛告大慧：譬如巨海浪，斯由猛风起，洪波鼓冥壑，无有断绝时。藏识海常住，境界风所动，种种诸识浪，腾跃而转生。青赤种种色，珂乳及石蜜，淡味众华果，日月与光明，非异非不异。海水起波浪，七识亦如是，心俱和合生。",
    "interpretation": "佛告大慧譬如巨海浪斯由猛风起洪波鼓冥壑无有断绝时——此是以海浪比喻藏识与转识之关系。藏识海常住境界风所动种种诸识浪腾跃而转生——藏识如海常住，境界如风所动，七识如浪腾跃而转生。海水起波浪七识亦如是心俱和合生——藏识与七识如海与浪非异非不异。",
    "master": "释迦牟尼",
