    "id": "koan-557",
    "question": "五法三自性",
    "answer": "五法者，名、相、妄想、正智、如如。三自性者，妄想自性、缘起自性、成自性。",
    "context": "佛告大慧：有五法、三种自性、八识、二种无我，一切诸佛声闻缘觉，演说示现。五法者，名、相、妄想、正智、如如。三自性者，妄想自性、缘起自性、成自性。八识者，阿赖耶识、末那识、意识、前五识。二种无我者，人无我、法无我。",
    "interpretation": "佛告大慧有五法三种自性八识二种无我——此是楞伽经之教理纲宗。五法者名相妄想正智如如——名相为所执，妄想为能执，正智为能观，如如为所证。三自性者妄想自性缘起自性成自性——妄想自性即遍计所执，缘起自性即依他起，成自性即圆成实。八识二无我——唯识与人法二无我之教理。",
    "master": "释迦牟尼",
    "source": "楞伽阿跋多罗宝经",
    "relatedConcepts": ["buddha-nature","self-nature"],
