    "id": "koan-562",
    "question": "宗通说通",
    "answer": "宗通者，谓缘自得胜进相，离言说妄想，离文字妄想。说通者，谓随众生心，应其所知，而为说法。",
    "context": "佛告大慧：有二种通，谓宗通及说通。宗通者，谓缘自得胜进相，离言说妄想，离文字妄想，趣无漏界，自觉地自相，远离一切虚妄觉想，降伏一切外道众魔，缘自觉趣光明晖发。说通者，谓随众生心，应其所知，而为说法。",
    "interpretation": "佛告大慧有二种通谓宗通及说通——此是楞伽经宗通说通之教。宗通者谓缘自得胜进相离言说妄想离文字妄想趣无漏界自觉地自相远离一切虚妄觉想降伏一切外道众魔缘自觉趣光明晖发——宗通是自证离言说妄想。说通者谓随众生心应其所知而为说法——说通是随众生心而为说法。此是禅宗宗通说通之源头——宗通自证说通化他。",
