    "id": "koan-565",
    "question": "食肉无慈悲",
    "answer": "食肉无慈悲，永背正解脱，及违圣表相，是故不应食。",
    "context": "佛告大慧：食肉无慈悲，永背正解脱，及违圣表相，是故不应食。得生梵志种，及诸修行处，智慧富贵家，斯由不食肉。大慧！菩萨摩诃萨，当观食肉如食子肉，作是观已，不食一切肉。",
    "interpretation": "佛告大慧食肉无慈悲永背正解脱及违圣表相是故不应食——食肉无慈悲永背正解脱及违圣表相。得生梵志种及诸修行处智慧富贵家斯由不食肉——不食肉之功德。菩萨摩诃萨当观食肉如食子肉作是观已不食一切肉——菩萨当观食肉如食子肉。此是楞伽经卷四断肉之教——食肉无慈悲永背正解脱。",
