    "id": "koan-569",
    "question": "三乘一乘",
    "answer": "三乘者，声闻乘、缘觉乘、佛乘。一乘者，佛乘也。",
    "context": "佛告大慧：三乘者，声闻乘、缘觉乘、佛乘。一乘者，佛乘也。大慧！我为众生说三乘法，为调伏众生故。大慧！然诸佛世尊，唯以一佛乘故，说三乘法。大慧！如是一切，皆是方便引导众生，令入一乘。",
    "interpretation": "佛告大慧三乘者声闻乘缘觉乘佛乘一乘者佛乘也——三乘与一乘。我为众生说三乘法为调伏众生故——说三乘法为调伏众生。然诸佛世尊唯以一佛乘故说三乘法——诸佛唯以一佛乘说三乘法。如是一切皆是方便引导众生令入一乘——三乘皆是方便引导众生令入一乘。此是楞伽经三乘一乘之教——三乘方便一乘真实。",
