    "id": "koan-570",
    "question": "苏轼序楞伽",
    "answer": "楞伽义辄幽渺，文字简古。读者或不能句，而况遗文以得义，忘义以了心者乎？",
    "context": "苏轼序云：楞伽阿跋多罗宝经——先佛所说微妙第一真实了义，故谓之佛语心品。祖师达磨以付二祖曰：吾观震旦所有经教，惟楞伽四卷可以印心。祖祖相授，以为心法。如医之难经，句句皆理、字字皆法。楞伽义辄幽渺，文字简古。读者或不能句，而况遗文以得义，忘义以了心者乎？此其所以寂寥於世，几废而仅存也。",
    "interpretation": "苏轼序楞伽经——先佛所说微妙第一真实了义故谓之佛语心品。祖师达磨以付二祖曰吾观震旦所有经教惟楞伽四卷可以印心——达磨以楞伽印心。如医之难经句句皆理字字皆法——楞伽如医之难经句句皆理字字皆法。楞伽义辄幽渺文字简古读者或不能句而况遗文以得义忘义以了心者乎——楞伽义幽渺文字简古读者或不能句。此其所以寂寥於世几废而仅存——楞伽经寂寥於世几废而仅存。",
    "master": "苏轼",
    "source": "楞伽阿跋多罗宝经",
    "relatedConcepts": ["buddha-nature","self-nature"],
