    "question": "禅门事例与毗尼是同是别？",
    "answer": "禅门事例虽无两样毗尼，衲子家风别是一般规范。",
    "context": "宗赜禅师《禅苑清规序》开篇明义：禅门事例虽无两样毗尼，衲子家风别是一般规范。若也途中受用自然格外清高，如其触向面墙实谓减人瞻敬。是以佥谋开士遍摭诸方，凡有补于见闻悉备陈于纲目。",
    "interpretation": "禅门规矩虽与戒律无两样，然衲子家风另是一般规范。禅宗虽不离戒律，然别立禅居、不居律寺，自有其独特之轨度。若能途中受用自然格外清高，如其触向面墙实谓减人瞻敬——禅门清规之设，正在于令衲子有轨可循、有规可依，自然清高而不堕轻慢。",
