    "question": "定水澄清时如何？",
    "answer": "探珠宜静浪，动水取应难，定水澄清，心珠自现。",
    "context": "宗赜禅师《坐禅仪》云：若不安禅静虑，到这里总是茫然。所以探珠宜静浪，动水取应难。定水澄清，心珠自现。故圆觉经云：无碍清净慧，皆依禅定生。法华经云：在于闲处，修摄其心，安住不动，如须弥山。",
    "interpretation": "以探珠为喻——探取海底明珠须在静浪之时，若水动则取珠应难。定水澄清则心珠自现，喻禅定成就时自性本心自然显现。不安禅静虑则到这里总是茫然——不在禅定中则无法亲见本心。圆觉经云无碍清净慧皆依禅定生，法华经云安住不动如须弥山，皆明禅定之要。",
