    "id": "koan-581",
    "question": "犯重之人当如何处治？",
    "answer": "犯重焚衣钵，应当集众人，山藤聊示耻，驱摈出偏门。",
    "context": "《禅苑清规·百丈规绳颂》云：或有所犯，即须集众以拄杖杖之，焚烧道具，逐从偏门而出者，示耻辱也。颂曰：犯重焚衣钵，应当集众人，山藤聊示耻，驱摈出偏门。详此条制有四种益：一不污清众生恭信心故，二不毁僧形徇佛制故，三不扰公门省狱讼故，四不洩于外护纲宗故。",
    "interpretation": "犯重罪者集众杖之、焚衣钵、逐出偏门——以山藤示耻辱、以偏门示降黜。此条制有四种益：不污清众生恭信心、不毁僧形徇佛制、不扰公门省狱讼、不洩于外护纲宗。然百丈又云：摈逐成何益，安禅不毁僧，公门无狱讼，祖席播嘉声——摈逐非为惩罚，而在安众护法。",
    "master": "百丈怀海",
    "source": "禅苑清规·百丈规绳颂",
    "relatedConcepts": ["baizhang-guisheng","conglin-zhidu"],
