    "question": "不饮虫水渴死生天者如何？",
    "answer": "宁死不亏虫水戒，刹那成道澄真常。",
    "context": "《禅苑清规·新添滤水法》云：鼻柰耶律说二比丘欲向佛所，一人不饮虫水渴死生天，见佛得道。颂曰：比丘来见法中王，忘却将行滤水囊，宁死不亏虫水戒，刹那成道澄真常。一比丘饮水后至佛所，佛问其故，已脱忧多罗，僧示黄金身，云：汝痴人，用观是四大身为幼成臭处，其见法者即见我身。",
    "interpretation": "二比丘向佛所，一人不饮虫水渴死生天见佛得道，一人饮水后至佛所只见黄金丈六躯。佛云：见法者即见我身——以身护戒者即见法身，破戒苟活者只见色身。宁死不亏虫水戒刹那成道澄真常——宁死不犯杀戒，刹那之间成道证真常。此明护戒之功德远胜破戒之苟活。",
