    "interpretation": "沙弥剃头时诵善哉大丈夫偈——赞叹能了世无常弃俗趣泥洹之大丈夫行。落发偈云毁形守志节割爱辞所亲出家弘圣道誓度一切人——明出家之志在毁形守节、割爱辞亲、弘圣道度一切人。最后一结谓之周罗唯佛一人乃能断之——表出家之功德究竟圆满唯佛能尽。",
