    "answer": "大哉解脱服，无相福田衣，披奉如来戒，广度诸众生。",
    "context": "《禅苑清规·沙弥受戒文》云：本师持袈裟诵偈云：大哉解脱服，无相福田衣，披奉如来戒，广度诸众生。沙弥披袈裟讫，礼本师三拜，礼圣像三拜，礼戒师三拜，胡跪合掌。",
    "interpretation": "披袈裟时诵大哉解脱服偈——袈裟是解脱之服、无相福田之衣。披奉如来戒广度诸众生——披袈裟非为装饰，而在披奉如来戒法、广度一切众生。袈裟又名福田衣——众生供养袈裟之人即种福田。此偈明袈裟之功德与出家之本怀。",
