    "interpretation": "八福田——佛法僧父母师长贫穷桥梁疾病——中看病第一。出家之人云游萍寄，一有疾病唯藉同袍慈悲安养。看病之功德最大，因为病人最苦最需关怀。若劝病人专念阿弥陀佛祈生净土，若劝率同袍打磬念之更妙。此明慈悲安养病僧为丛林第一福田。",
