    "question": "斋僧之法以何为宗？",
    "answer": "斋僧之法以敬为宗，但依僧次延迎，不得妄生轻重。",
    "context": "《禅苑清规·斋僧仪》云：斋僧之法以敬为宗，但依僧次延迎，不得妄生轻重。凡夫肉眼谁辨圣贤，误起轻心定招薄福。然而清净福田理应专一，不宜多招宾客杂乱正因。设斋之日亦应慎护三业，不得饮酒食肉。若能如此，福德无量。",
    "interpretation": "斋僧以敬为宗——依僧次延迎不得妄生轻重。凡夫肉眼谁辨圣贤——不可分别僧众高下，误起轻心定招薄福。清净福田理应专一——设斋当专一清净不宜杂乱。慎护三业不饮酒食肉——设斋之日当护三业。如此则福德无量。此明斋僧之要在敬与平等。",
