    "id": "koan-590",
    "question": "住持人当如何运心？",
    "answer": "代佛扬化，表异知事，运大心演大法，蕴大德与大行，廓大慈悲作大佛事成大利益。",
    "context": "《禅苑清规·尊宿住持》云：代佛扬化表异知事故云传法，各处一方续佛慧命斯曰住持。初转法轮命为出世，师承有据乃号传灯。得善现尊者长老之名，居金粟如来方丈之地。私称洒扫贵徒严净道场，官请焚修盖为祝延圣寿。故宜运大心演大法，蕴大德与大行，廓大慈悲作大佛事成大利益。权衡在手纵夺临時，规矩准绳故难拟议。然其大体令行禁止必在威严，形直影端莫如尊重。",
    "interpretation": "住持人之位是代佛扬化、续佛慧命——代佛扬化表异知事，各处一方续佛慧命。当运大心演大法、蕴大德与大行、廓大慈悲作大佛事成大利益。权衡在手纵夺临时——住持之权在权衡纵夺，然规矩准绳故难拟议。令行禁止必在威严，形直影端莫如尊重——住持当以威严令行禁止、以尊重形直影端。",
    "master": "宗赜",
    "source": "禅苑清规·尊宿住持",
