    "answer": "一生事办否，得人自在否，证大涅槃否。",
    "context": "《禅苑清规·一百二十问》最后三问：一生事办否，得人自在否，证大涅槃否。此为百二十问之归结——从敬佛法僧、求善知识、发悟菩提开始，历经壁立千仞、常好坐禅、对境不动、般若现前、慈悲开示、护法亡躯、处众如山、和合无诤、行施不倦、敬老慈幼、怨亲平等、普敬如佛，终至一生事办、得人自在、证大涅槃。",
    "interpretation": "百二十问以一生事办否、得人自在否、证大涅槃否为归结——此是修行之终极目标。一生事办——此生修行事业是否成办；得人自在——于人境中是否得自在；证大涅槃——是否证得大涅槃。从初发心敬三宝至证大涅槃，涵盖修行全历程。学人当时时以此三问自省。",
