    "question": "巴陵如何为云门作忌？",
    "answer": "巴陵三转语报答云门深恩。",
    "context": "《敕修百丈清规·尊祖章·嗣法师忌》载：“先德唯激扬宗乘发明自己，开示后学知有授受，以报恩也。如巴陵三转语为云门作忌，前辈深有意焉。”昔巴陵颢鉴禅师以三转语（鸡寒上树、金将火试、透网金鳞）呈云门，云门曰：“他日我不患无后矣，开忌日不用肉，但读此三转语供养我足矣。”",
    "interpretation": "世人祭祖以牲醴香华，禅门祭祖以自性心印。巴陵三转语透彻云门宗风，云门闻之喜其得人，以真悟为最好供养。清规引此明嗣法师忌之重在激扬宗乘、发扬己悟，非仅世俗追远之文也。",
