    "interpretation": "百丈不立佛殿唯立虚堂，僧堂普请天下均力，开中国禅林千古独立之基。司马头陀之预言非仅指山川形胜，实悬指百丈清规将为普天下学人所依止轨范。法王居之，人法相应，千秋师表。",
