    "context": "《胜鬘经》云：‘有二法难可了知：谓自性清净心，难可了知；彼心为烦恼所染，亦难可了知。’宗门宗师以此勘验学人是否落在净秽两边二元对立之中。",
    "interpretation": "自性未曾有一刻真正被染污，所谓‘染’者，只是妄识计执之客尘幻象；若认烦恼为实法而欲排遣除灭，是名头上安头；若执本来清净而放浪形骸，是名狂野狐禅。唯当下截断能所分别，始见真常。",
    "master": "胜鬘夫人",
    "source": "《胜鬘师子吼一乘大方便方广经》",
