    "interpretation": "诸佛说法皆是筌蹄标月，达摩面壁亦是方便接人。学人向故纸堆中寻言索句，终是数他人珍宝。超宗禅师一声‘札’截断意根，指出人人顶后亘古圆明之神光，当下即是极则，更无第二公案。",
