    "question": "永明听瀑",
    "answer": "扑落非他物，纵横不是尘。山河及大地，全露法王身！",
    "context": "永明延寿禅师初参天台德韶国师，于天台山天柱峰苦修禅定。一日于瀑布之畔经行，忽闻飞瀑堕石震响，若天崩地裂，豁然身心粉碎，脱体无依，当下大彻大悟。德韶国师闻之印可曰：“汝与永明有缘，他日当大振玄风。”延寿禅师遂作偈记悟。",
    "interpretation": "延寿禅师以瀑布声震顿断情识，声非心外之物，自性唯心，森罗万象皆是法身显现。其《唯心诀》云“高低岳渎共转根本法轮，大小鳞毛普现色身三昧”，正是这一境界之彻底宣流。",
