    "interpretation": "德韶发问时，心外求水，把“曹源一滴水”看作高不可攀的圣境；文益原话奉还，直截指破：问的这个当下便是那一滴真水，何处更去寻觅！一语粉碎学人情识，直显“一切现成”之无上大机。",
