    "id": "koan-672",
    "question": "空对一切见，于空生见佛不能救",
    "answer": "药能疗病，药若成病，虽有神医扁鹊无如之何！大圣说空正破诸见，汝今反在空里安身立命，正是自掘坟墓！",
    "context": "《顺中论》卷下引龙树大士破空见之义：外人闻一切法空、因缘生法皆无自性，便谓“既一切法皆空，则空亦是一法，我今守此空以为了脱”。无著菩萨引大圣教痛呵之：“诸佛说空，为令众生离一切有无颠倒执见；若人复于空法生起实有之解，坚执空相，是人不可救疗。”犹如服药本为驱病，病去而药性积聚作祟，神医亦束手无策。",
    "interpretation": "宗门历代祖师对此警惕尤深。学人初入道时，喜以“四大皆空、万法本无”为标榜，口谈玄虚，拨无因果，即是“执空为实”。此则公案揭露：真正般若非是有空对待之相，若存一毫“空”之见解，正是生死根本。须将“空”亦彻底打破，真空无滞，大用现前，方免作泥塑木雕之枯禅汉。",
    "master": "龙树菩萨 / 无著菩萨",
