    "id": "koan-673",
    "question": "尚无有色，何常何无常",
    "answer": "镜里寻发，水中摸月！连个色相影子且不可得，你向何处商量常与无常？",
    "context": "《顺中论》卷上论主设问辨析：“若人观色是无常、受想行识是无常，此是真般若否？”论主断然答曰：“非也！此是相似般若。何以故？真实般若波罗蜜不见色常、不见色无常；不见受想行识常、不见无常。乃至色自体本不可得，尚无有色，云何当见色若常若无常耶？”",
    "interpretation": "常情皆认“破常执、知无常”便算通达佛法，实则仍落在有无能所之相网之中。论主以金刚利剑彻底斩绝知解：五蕴本自缘起性空，其本体如空华水月，本无自性实体，又何来“常”可守、何来“无常”可叹？宗门直指“法本法无法”，向无物处撒手承当，不见一法立，方是亲见实相。",
