    "id": "koan-676",
    "question": "好雪片片不落别处",
    "answer": "眼见如盲，口说如哑！头头现成处，你向何处寻别处？！",
    "context": "庞居士辞别药山惟俨禅师，药山命十位禅客相送至山门。居士指空中纷飞大雪叹曰：“好雪片片，不落别处！”送行之全禅客出声问：“落在甚处？”居士当即打其一掌。全禅客曰：“也不得草草！”居士曰：“恁么称禅客，阎罗老子未放你在！”全禅客复问：“居士作么生？”居士又打一掌曰：“眼见如盲，口说如哑！”",
    "interpretation": "天地之间，万法森罗，何处不是实相真常？全禅客偏要在“不落别处”的当下，再生起一个“落在甚处”的思维分别，正是头上海安头、骑驴觅驴。居士两掌痛打，如金刚迅雷，斩断学人一切向外推求的虚妄知解。明眼人看取：片片雪花当处即是，何曾离开自性半步！",
    "master": "庞蕴居士",
    "source": "《庞居士语录》卷上、《碧岩录》第四十二则",
