    "id": "koan-677",
    "question": "但愿空诸所有",
    "answer": "枕膝撒手归大化，世间万相如影响！赤裸裸无一物，何处不逍遥！",
    "context": "庞居士预知时至，命女灵照视日。灵照遽报“日已中而有蚀”，居士出户观之，灵照即登父座合掌坐亡。居士笑曰：“我女锋捷矣！”更延七日。襄州刺史于頔节度使亲临草庵问疾，居士执于公手，遗诫曰：“但愿空诸所有，慎勿实诸所无。好住世间，皆如影响。”言讫，安枕于公膝而化。",
    "interpretation": "生死大事在庞公一家手中，如同儿戏般自由洒脱！女儿抢先坐脱，父亲从容含笑延期；临终遗诫于頔节度使十六字，倾吐出一代维摩大士毕生修持的心髓：凡夫之所以生死流转，皆因实执外境；若能空其所有，而不立所无，当下身心世界皆如幻影，即是无上大涅槃。",
