    "id": "koan-679",
    "question": "自断其首无能断",
    "answer": "宝剑横挥头落地，虚空粉碎绝能所！既无断者，更唤谁作主人公？！",
    "context": "侍读大学士员峤李总管雅好佛法，向海印昭如禅师请益深心大道。师特示法语云：“迷时迷个悟底，悟时悟个迷底，迷悟两忘。譬如有人自断其首，首已断故，无能断者。见此明白，直下无第二念。古德道：明明无悟，有法即迷！”",
    "interpretation": "世间学禅之人，最难勘破的是潜伏在深层的“能所我执”——自以为有一个“正在参禅的我”，妄想去求得一个“高深莫测的佛果”。海印禅师以自斩其首之绝烈机锋，彻底斩断学人的第二念思维：头颅落地之时，能断与所断同归于尽，当下虚空粉碎、大地平沉，方是本来真面目！",
