    "question": "持戒皮禅定肉微妙髓",
    "answer": "皮骨剥尽体全露，微密心印是真髓！离却名相阶级，谁在内外横生分别？！",
    "context": "北宋义学者每每以戒律严整、禅定深固自矜，讥讽宗门教外别传为虚诞。契嵩大师在《传法正宗论》第二篇中当头痛击，引达摩考门人公案设难：“达磨考验门人，道副得皮，总持得肉，道育得骨，神光慧可得髓。诸家义学且道：持戒是皮乎？禅定是肉骨乎？大迦叶破颜微笑所得者，又是何物？”讲僧皆茫然不能对。契嵩喝曰：“持戒止于戒，修定局于定，不过二乘外道常途；唯有先佛微密不可思议实相智慧，方是如来无上真髓！”",
    "interpretation": "达摩断臂传衣、考验四门人，古今注家多作阶次高下之解；契嵩大师独具宗眼，将其与戒定慧三学精妙贯通：持戒如皮毛御外非，禅定如肌肉骨骼制妄乱，若无向上一着微密智慧之髓，则戒定皆成死尸无魂之具。学人参禅，切莫在枝末皮相上计较工夫，直探骨髓深处那颗不生不灭之自性心印，方是真得祖脉。",
    "master": "菩提达摩 / 契嵩",
    "source": "《传法正宗论》第二篇、《景德传灯录》卷三",
    "relatedConcepts": ["sanzang-lingfu","jiaowai-biechuan-zhengzong","wuxin-jueguan"],
    "relatedPersons": ["bodhidharma","huike","qisong"],
    "relatedBooks": ["chuanfazhengzonglun","chuanfazhengzongdingzutu"]
