    "id": "koan-682",
    "question": "希叟佛陇挑正眼",
    "answer": "山僧今日住此佛陇，为汝诸人挑出顶门金刚眼去也！",
    "context": "希叟绍昙禅师首住庆元府佛陇寺开堂升座。提持宗乘云：“古德道：目前无法，意在目前。不是目前法，非耳目之所到。大众！既非耳目之所到，且道阿谁知得？若向个里知得，尽十方世界是自己眼睛；若向个里不知，却被目前法障却本来面目。山僧今日住此佛陇，为汝诸人挑出顶门金刚眼去也！”言毕，卓拄杖一下，一时下座。大众如雷惊梦，绝诸知解。",
    "interpretation": "古德言‘目前无法’，断绝行者向外攀缘色尘之妄见；言‘意在目前’，截断死守空无死寂之断灭偏病。希叟绍昙卓拄杖一声，如电光裂石，直将学人向外摸索之眼根耳识一齐打失，顶门正眼当下豁开。",
    "master": "希叟绍昙",
