    "id": "koan-683",
    "question": "希叟示日本国光",
    "answer": "莫向沧溟弄钓钩，归去建长重举起！",
    "context": "日本建长寺兰溪道隆弟子国光上座，梯山航海东渡大宋，入室参礼希叟绍昙禅师于雪窦。参扣积年，豁蒙印证。及辞归东瀛，希叟作偈送之云：“航海梯山志气豪，归囊收拾尽秋毫。莫向沧溟弄钓钩，归去建长重举起！”国光作礼拜辞，将杨岐正眼重播海东，建长宗风大振。",
    "interpretation": "跨越万顷沧溟求法，所得者非文字筌蹄，乃不可动摇之顶门正印。希叟嘱其‘莫向沧溟弄钓钩’，戒其贪着于沿途风光与语言知解；‘归去建长重举起’，命其荷担佛祖大法印，直下在东瀛扶竖临济家风。",
    "master": "希叟绍昙",
    "source": "希叟绍昙禅师语录卷三",
    "relatedConcepts": ["dong-du-chuan-fa","jin-ding-zi"],
    "relatedPersons": ["xisou-shaotan"],
    "relatedBooks": ["xisouyulu"]
