    "question": "脱去鹘臭布衫与打碎鬼窟",
    "answer": "直得净裸裸、赤洒洒，犹是半提，更须大死一番始得！",
    "context": "直翁居士参无见禅师，自述坐禅稍有所悟，觉天地清虚、内外明彻，心大欢喜。禅师迎头棒喝道：“莫在此认贼作子！你如今正被这领‘鹘臭布衫’罩定，死在光影鬼窟里受用，自谓极则。若不彻底脱却这领臭布衫，打碎光影窠臼，直得净裸裸、赤洒洒，阎罗老子定不放你过！”直翁愕然失措，方省前非，顿起真实疑情。",
    "interpretation": "禅门修证最忌以幻为真、贪恋清净境界。先睹禅师大机大用，如金翅鸟擘海直取龙吞，当头粉碎学人之微细法执，尽显宗门大机杀活之绝顶手眼。",
    "master": "无见先睹",
    "source": "天台无见先睹禅师语录卷一示直翁",
