    "id": "koan-688",
    "question": "华顶峰头沙鸥冷眼见深秋",
    "answer": "寒风卷雪入枯篱，沙鸥冷眼知深意，不向浮云问所思！",
    "context": "有行脚僧慕无见禅师大名，历尽艰险攀登天台山华顶峰善兴精舍，见禅师独自拥衲坐于残雪乱石间，神色严冷如铁。僧稽首问：“绝顶风雪刺骨，和尚孤坐四十年，究竟为何大事？”禅师徐徐抬眼，指篱外苍茫天宇，随口吟道：“华顶峰头独坐时，寒风卷雪入枯篱。沙鸥冷眼知深意，不向浮云问所思。”僧当下拟议，禅师拂袖而起，寂然无语。",
    "interpretation": "先睹禅师四十年隐修绝顶，其境其心浑然与太虚同体。山居绝唱不仅是冷峻孤高之隐修写照，更是彻底绝断世间名闻利养、独露法身廓然无圣之真实受用。",
