    "question": "黄龙拳头打破触背牢关",
    "answer": "直须打破牢关，总是自家行履！",
    "context": "晦堂祖心和尚每在室中，握拳示来参学者问曰：‘若作拳见即触，不作拳见即背。上座如何见？’学人拟欲开口商量，禅师便叱退之。后自作三颂示众：‘黄龙有个拳头，不论得皮得髓。分明直下相呈，早是和泥合水。黄龙有个拳头，举起别无道理。直须打破牢关，总是自家行履。’",
    "interpretation": "常人处世非有即无，见拳落相，不作拳见落空。晦堂以此千钧拳头当头立起，断除学者意识葛藤。不向言句商量，自能打破牢关，全心履践自家真修。",
    "master": "晦堂祖心",
