    "question": "向上大事与著衣吃饭",
    "answer": "著衣吃饭有甚难？",
    "context": "僧上堂请问晦堂祖心禅师：‘王子未登九五之位时如何？’师曰：‘入乡顺俗。’僧曰：‘登位后如何？’师曰：‘四海五湖王化里。’僧追问：‘未审向上还有大事也无？’师曰：‘有。’僧急问：‘如何是向上大事？’师曰：‘著衣吃饭有甚难？’僧当下拟议，师曰：‘礼繁即乱。’",
    "interpretation": "学者常起分别，以为‘登位成佛’之后必另有奇特玄秘之‘向上事’。晦堂一语点破：至道无他，唯在日用寻常中著衣吃饭、饥餐渴饮。离了平常行履，另寻奇特，皆是无事生非的妄想羁绊。",
