    "question": "无山不带云有水皆含月",
    "answer": "千峰对立白云间，市井红尘白日闲。带水含月全无二，随方作主大安澜！",
    "context": "石屋清珙住持嘉兴福源禅寺上堂，问大众：‘山僧前居天湖茅庵，门对千峰，朝看白云，暮听流水，是非不到；今住院时，门连湖市，红尘滚滚，迎送纷纭。且道住湖寺与居山庵，是同是别？’大众无对。师良久示曰：‘无山不带云，有水皆含月！’遂喝一喝，下座。",
    "interpretation": "常人将山林与闹市分作二界，恋山厌市，堕在取舍泥坑。石屋一语‘带云含月’，将动静两端彻底化除。月印万川，云横千岫，真如妙体何曾被环境所迁？",
    "master": "石屋清珙",
    "source": "石屋清珙禅师语录卷上",
    "relatedConcepts": ["dongjing-buer","shanju-chan"],
