    "question": "太古直钩金鳞上",
    "answer": "万里梯航入翠微，直钩钓得老鲸归。海东从此传真印，白雪青山同落晖！",
    "context": "高丽僧太古普愚跨海来华，历尽艰险登天湖霞雾山参礼石屋清珙。石屋勘问个事，普愚言下投机，彻见根源。石屋欣然解所披袈裟并达摩血脉法卷付之，并亲书赠诗曰：‘海东禅子太古愚，入室相逢语意投。不用安排巧言句，金鳞原上直横钩。’普愚受法回国，尊为国师，开创太古宗，临济正眼自此永镇海东。",
    "interpretation": "宗门正眼，不问方隅与邦国，唯认顶门具眼。石屋不惜眉毛，直钩下处钓得透海金鳞；太古直下承当，将中华禅髓续命海外，谱写中韩禅史千古佳话。",
    "master": "石屋清珙",
